    "id": "navidad-mood",
    "titulo": "Moodboard",
    "html": "<section class=\"papel\" style=\"\"><h2 class=\"marker\" style=\"position:absolute;left:120px;top:100px;white-space:nowrap;font-size:84px;color:#111111;transform:rotate(-3deg);transform-origin:left center;\">Moodboard</h2><svg width=\"520\" height=\"36\" viewBox=\"0 0 520 36\" style=\"position:absolute;left:100px;top:204px;transform:rotate(-2deg);opacity:1;overflow:visible\"><defs><filter id=\"dv44\" x=\"-5%\" y=\"-40%\" width=\"110%\" height=\"180%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\"0.035 0.55\" numOctaves=\"3\" seed=\"28\"/><feDisplacementMap in=\"SourceGraphic\" scale=\"16\"/></filter></defs><path d=\"M11 12 Q260 4 513 11 L507 28 Q234 32 5 26 Z\" fill=\"#D4FB04\" filter=\"url(#dv44)\"/></svg><span class=\"etiqueta\" style=\"position:absolute;left:120px;top:300px;transform:rotate(-2deg);background:#D80036;color:#fff;font-size:20px\">Paleta</span><p style=\"position:absolute;left:120px;top:350px;width:720px;font-size:24px;line-height:1.42;font-weight:500;color:#222;\">El rojo y la lima de siempre, con el dorado del décimo y el blanco del papel de la focaccia. Nada de verde abeto.</p><span class=\"etiqueta\" style=\"position:absolute;left:120px;top:490px;transform:rotate(-2deg);background:#D80036;color:#fff;font-size:20px\">Tipografía</span><p style=\"position:absolute;left:120px;top:540px;width:720px;font-size:24px;line-height:1.42;font-weight:500;color:#222;\">La brocha de Divorare sobre el formato clásico del décimo de lotería: números grandes, sellos y series.</p><span class=\"etiqueta\" style=\"position:absolute;left:120px;top:680px;transform:rotate(-2deg);background:#D80036;color:#fff;font-size:20px\">Atmósfera</span><p style=\"position:absolute;left:120px;top:730px;width:720px;font-size:24px;line-height:1.42;font-weight:500;color:#222;\">Colas de diciembre, abrigos, luces de calle, el directo del sorteo en la tele del bar y el grito al ver el número.</p><div style=\"position:absolute;left:900px;top:140px;width:560px;height:280px;transform:rotate(-5deg);filter:drop-shadow(0 18px 28px rgba(0,0,0,.35))\"><div style=\"position:relative;width:100%;height:100%;background:#FBFAF7 url(/pitch/divorare/doodles.jpg) 0 0/300px auto;border:4px solid #111111;border-radius:7px;overflow:hidden\"><div style=\"position:absolute;left:0;top:0;width:162px;height:100%;background:#D80036\"></div><img src=\"/pitch/divorare/logo-llama.webp\" alt=\"\" style=\"position:absolute;left:21px;top:44px;width:122px;filter:brightness(0) invert(1)\"><p style=\"position:absolute;left:184px;top:19px;font-size:13px;font-weight:800;letter-spacing:2.2px\">SORTEO DEVORADOR · 22 DIC 2026</p><p class=\"marker\" style=\"position:absolute;left:184px;top:46px;font-size:47px;line-height:1;transform:rotate(-3deg)\">El Gordo</p><p class=\"marker\" style=\"position:absolute;left:221px;top:94px;font-size:47px;line-height:1;color:#D80036;transform:rotate(-3deg)\">se devora</p><p style=\"position:absolute;left:184px;top:169px;font-family:Anton, Impact, sans-serif;font-size:63px;line-height:1;letter-spacing:3px\">17 048</p><p style=\"position:absolute;right:18px;bottom:13px;font-size:11px;font-weight:700;color:#5A5A5A\">Valor: 1 focaccia</p></div></div><img class=\"recorte\" src=\"/pitch/divorare/packaging.webp\" alt=\"\" style=\"position:absolute;left:1560px;top:90px;width:270px;height:auto;transform:rotate(4deg);\"><img class=\"recorte\" src=\"/pitch/divorare/tienda-noche.webp\" alt=\"\" style=\"position:absolute;left:880px;top:520px;width:460px;height:auto;transform:rotate(3deg);\"><img class=\"foto\" src=\"/pitch/divorare/foto-focaccias-oscuro.jpg\" alt=\"\" style=\"position:absolute;left:1360px;top:600px;width:470px;height:300px;transform:rotate(-3deg);\"><div style=\"position:absolute;left:120px;top:880px;display:flex;gap:16px\"><span style=\"width:90px;height:90px;background:#D80036;border:3px solid #111111;display:block;transform:rotate(-3deg)\"></span><span style=\"width:90px;height:90px;background:#D4FB04;border:3px solid #111111;display:block;transform:rotate(2deg)\"></span><span style=\"width:90px;height:90px;background:#C9A227;border:3px solid #111111;display:block;transform:rotate(-1deg)\"></span><span style=\"width:90px;height:90px;background:#FBFAF7;border:3px solid #111111;display:block;transform:rotate(3deg)\"></span><span style=\"width:90px;height:90px;background:#111111;border:3px solid #111111;display:block;transform:rotate(-2deg)\"></span></div><div style=\"position:absolute;left:96px;top:1018px;width:1728px;display:flex;justify-content:space-between;font-size:17px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:rgba(17,17,17,.55)\"><span>Maen Studios × Divorare</span><span>35</span></div></section>"
