    "id": "cierre",
    "titulo": "Grazie mille",
    "html": "<section class=\"asfalto\" style=\"\"><img src=\"/pitch/divorare/foto-focaccias-oscuro.jpg\" alt=\"\" style=\"position:absolute;left:0px;top:0px;width:1920px;height:1080px;object-fit:cover;opacity:.55\"><h1 class=\"anton\" style=\"position:absolute;left:120px;top:200px;white-space:nowrap;font-size:240px;color:#fff;\">¿Devoramos</h1><h2 class=\"marker\" style=\"position:absolute;left:160px;top:440px;white-space:nowrap;font-size:220px;color:#D80036;transform:rotate(-4deg);transform-origin:left center;\">juntos?</h2><p style=\"position:absolute;left:120px;top:720px;width:1000px;font-size:32px;line-height:1.42;font-weight:600;color:#fff;\">Gracias por invitarnos al proceso. Nos encantaría presentaros todo esto en persona.</p><p style=\"position:absolute;left:120px;top:820px;width:1200px;font-size:28px;line-height:1.42;font-weight:700;color:#D4FB04;\">Jandro Martín · jandro@maenstudios.com · +34 688 629 688</p><img src=\"/maen-logo.png\" alt=\"Maen Studios\" style=\"position:absolute;left:120px;top:900px;width:360px;height:auto;\"><img src=\"/pitch/divorare/logo-llama.webp\" alt=\"Divorare\" style=\"position:absolute;left:1440px;top:300px;width:360px;height:auto;transform:rotate(6deg)\"><svg width=\"160\" height=\"115\" viewBox=\"0 0 120 86\" style=\"position:absolute;left:1530px;top:170px;transform:rotate(8deg)\"><path d=\"M12 78 L8 26 L36 52 L58 12 L80 50 L110 22 L104 78 Z\" fill=\"none\" stroke=\"#D4FB04\" stroke-width=\"7\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><circle cx=\"8\" cy=\"20\" r=\"6\" fill=\"#D4FB04\"/><circle cx=\"58\" cy=\"6\" r=\"6\" fill=\"#D4FB04\"/><circle cx=\"111\" cy=\"16\" r=\"6\" fill=\"#D4FB04\"/></svg><div style=\"position:absolute;left:96px;top:1018px;width:1728px;display:flex;justify-content:space-between;font-size:17px;font-weight:700;letter-spacing:3px;text-transform:uppercase;color:rgba(244,244,244,.6)\"><span>Maen Studios × Divorare</span><span>38</span></div></section>"
